sys_script_include.script:
var ProjectAPI = Class.create();
ProjectAPI.CONSTANTS = {
    API_CONFIG: {
        DRIVE_TRANSFER: {
            path: "/v2/projects/${projectId}/locations/${locationId}/jobs/${jobName}:run",
            httpMethod: "POST",
            pathParams: ["projectId", "locationId", "jobName"],
            content: {
                ticket_number: {
                    required: true
                },
                owner_email: {
                    required: true
                },
                new_owner_email: {
                    required: true
                },
                target_file_ids: {
                    required: true
                },
                dry_run: {
                    required: true
                },
                preserve_permissions: {
                    required: true
                }
            }
        }
    }
};
ProjectAPI.prototype = Object.extend(new x_neyu_google_nyu.RestUtil(), {
    initialize: function() {
        this.oauthProvider = "ece763ebeba1c7105c06fcffcad0cded";
        this.providerProfile = "43386bebeba1c7105c06fcffcad0cd14";
        this.credential = gs.getProperty("x_neyu_google_nyu.project.api.credential.id");
        this.aliasId = "fc5ecb172ba5c310da0ef1bece91bf74";
    },

    driveTransfer: function(
        projectId,
        locationId,
        jobName,
        ticketNumber,
        ownerEmail,
        newOwnerEmail,
        fileIds,
        dryRun = true,
        preservePermssions = true) {
        gs.info(`[driveTransfer] ticketNumber: ${ticketNumber}` +
            `\nownerEmail: ${ownerEmail}` +
            `\nnewOwnerEmail: ${newOwnerEmail}` +
            `\nfielIds: ${fileIds}` +
            `\ndryRun: ${dryRun}` +
            `\npreserverPermissions: ${preservePermssions}`);

        if (!ticketNumber || !ownerEmail || !newOwnerEmail || !fileIds ||
            !projectId || !locationId || !jobName) {
            gs.error("[driveTransfer] There were missing required fields.");
            return {
                error: true,
                errorMessage: "There are empty required parameters",
                status: 400
            };
        }

        this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);

        const config = ProjectAPI.CONSTANTS.API_CONFIG.DRIVE_TRANSFER;
        const {
            content: spec
        } = config;
        const content = {
            ticket_number: ticketNumber,
            owner_email: ownerEmail,
            new_owner_email: newOwnerEmail,
            target_file_ids: fileIds,
            dry_run: dryRun,
            preserve_permissions: preservePermssions
        };

        // validate content specification
        if ((errors = this.validateContent(spec, content))) {
            const errorMessage = Object.entries(errors)
                .map(([k, v]) => v?.error)
                .join("\n");
            return {
                error: true,
                status: 400,
                errorMessage: errorMessage
            };
        }

        const postBody = JSON.stringify({
            overrides: {
                containerOverrides: [{
                    env: [{
                        name: "SNOW_PAYLOAD",
                        value: JSON.stringify(content)
                    }]
                }]
            }
        });

        const pathParams = {
            projectId: projectId,
            locationId: locationId,
            jobName: jobName
        };

        const requestConfig = {
            ...config,
            pathParams,
            content: postBody,
            aliasId: this.aliasId
        };

        const response = this.execute(requestConfig, "driveTransfer");

        if (response.error && response?.status != 500) {
            gs.error(`[driveTransfer] There was an error returned from the Project API` +
                `\nResponse: ${JSON.stringify(response)}`);
        }

        return {
            ...response
        };
    },

    type: 'ProjectAPI'
});
